"""Curate source-bounded rules. This is authored interpretation, not automatic extraction. MIT."""
import json,pathlib,re
from engine import BASE,ROOT,norm
S=json.loads((BASE/'sources.json').read_text());sources={d['id']:d for d in S['sources']}
def cite(sid,page,start,end=None):
    text=norm((ROOT/sources[sid]['text']).read_text().split('\f')[page-1])
    a=text.index(start);b=text.index(end,a)+len(end) if end else a+len(start)
    return {'source_id':sid,'pdf_page':page,'quote':text[a:b]}
def eq(field,value):return {'op':'eq','field':field,'value':value}
def isin(field,values,domain):return {'op':'in','field':field,'values':values,'domain':domain}
def experience(cid,label,collection,quote,units,qualifiers,field,owner,action,discretion=None):
    bindings=[{'id':'min_units','citation_index':0,'regex':r'at least (?:sixty|seventy) \((\d+)\)(?: Experience)? residential units','value':units}, {'id':'lookback','citation_index':0,'regex':r'within the past (seven)(?: \(7\))? years','value':7}]
    where={'op':'all','args':[{'op':'gte','field':'residential_units','value':units,'binding':'min_units','unit':'dwelling_units'}, {'op':'within_years','field':field,'value':7,'binding':'lookback','unit':'calendar_years'},*qualifiers]}
    return {'id':cid,'label':label,'kind':'experience','collection':collection,'where':where,'bindings':bindings,'citations':[quote]+([discretion] if discretion else []),'on_no_match':'agency_review' if discretion else 'fail','discretion_citation':1 if discretion else None,'owner':owner,'next_action':action,'interpretation':'Numeric predicates are source-bound. Credential field meanings and role/ownership applicability require scoped human review.'}
def manual(cid,label,citations,owner,action):
    return {'id':cid,'label':label,'kind':'review','citations':citations,'owner':owner,'next_action':action,'interpretation':'Requires a scoped evidence-backed review; document presence alone cannot pass this gate.'}
role_domain=['owner_and_manager','owner_through_management_entity','manager_without_ownership','other']
work_domain=['new_construction','substantial_rehabilitation','other']
cases=[]
for key,title,cutoff,min_units in [('west169','97 West 169th Street','2019-04-04',60),('stanns',"St Ann’s Avenue and East 142nd Street",'2015-05-22',70)]:
    if key=='west169':
        dev=cite('west169_rfp',19,'At least one Principal must have, as Principal,','within the past seven (7) years.')
        mgmt=cite('west169_rfp',19,'Residential: At least one Principal','to fulfill this qualification.')
        extras=[manual('submission.completeness','Complete submission and current addenda',[cite('west169_rfp',17,'The Submission must contain each Tab','request for clarification.'),cite('west169_rfp',26,'Each Respondent must submit','further consideration.'),cite('west169_add3',2,'There is no Form e-4','format you prefer.')],'Project manager','Expand every required tab/form/attachment, reconcile addenda, and verify each artifact; absent E-4 is not a blocker.'),
        manual('team.adverse_findings','Applicant and associated-party adverse findings',[cite('west169_rfp',19,'Submission may be rejected','request for clarification).')],'Counsel','Collect entity/principal disclosures and review adverse findings; no clearance inferred.'),
        manual('team.roles','Required qualified team and general contractor',[cite('west169_rfp',19,'At a minimum, the Development Team','environmental planner and engineer.'),cite('west169_add1',3,'Q13: The criteria refer','A13: Yes.'),cite('west169_add3',2,'The development team’s real','in the proposed project.')],'Project manager','Identify team members, roles and qualifications; counsel experience must fit proposed elements.'),
        manual('team.capacity','Capacity and commitments',[cite('west169_rfp',19,'The Development Team must submit','timeframes delineated.')],'Developer principal','Provide capacity statement and current workload/obligations evidence.'),
        manual('proposal.schedule','Development schedule and phasing',[cite('west169_rfp',19,'A detailed schedule','A phasing plan, if applicable.')],'Project manager','Evidence schedule feasibility and anticipated approval dependencies.'),
        manual('proposal.finance_feasibility','Feasible sources uses and operations',[cite('west169_rfp',21,'The proposed Project must be in compliance','other sources.')],'Finance lead','Provide cost estimates, comparables, term-sheet compliance and supported capital/operating scenarios.'),
        manual('team.financial_capacity','Ability to secure financing',[cite('west169_rfp',21,'Asset statements must demonstrate','proposed Project.')],'Finance lead','Provide assets, lender indications and evidence of financial commitments.'),
        manual('proposal.program','Senior affordability and compliant program',[cite('west169_rfp',23,'Affordability. 100%','years.')],'Developer and housing-program lead','Review senior eligibility, unit mix and restriction terms against applicable term sheets.'),
        manual('proposal.community','Hiring and procurement obligations',[cite('west169_rfp',23,'Local Hiring/M/WBE.','Build-up Programs.')],'Project manager','Prepare supported hiring/procurement plan and applicable compliance evidence.'),
        manual('proposal.zoning','Zoning and design compliance',[cite('west169_rfp',17,'Design and Performance','• Zoning Compliance'),cite('west169_rfp',24,'The Projects must conform','zoning requirements.')],'Architect and zoning counsel','Provide sourced applicable zoning/code and concept review; no entitlement inferred.')]
        discretion=None
    else:
        dev=cite('stanns_rfp',18,'At least one Principal of the Applicant must have had','within the past seven years.')
        mgmt=cite('stanns_rfp',18,'At least one Principal of the Applicant or the proposed managing agent','prior HPD approval.')
        discretion=cite('stanns_add1',3,'Q15: The RFP indicates','experienced team.')
        extras=[manual('submission.completeness','Complete proposal and required attachments',[cite('stanns_rfp',18,'The Proposal must contain','clarification is necessary.'),cite('stanns_add1',4,'Q18: On page 21','former multi-site RFP.')],'Project manager','Expand required forms/attachments; disregard obsolete separate-multiple-site instruction per addendum.'),
        manual('team.capacity','Development capacity and current workload',[cite('stanns_rfp',18,'Applicants must be capable','Project.')],'Developer principal','Review workload, obligations and capacity to meet required timeline.'),
        manual('proposal.conformance','Conformance to minimum program requirements',[cite('stanns_rfp',18,'Proposed Project must meet','Requirements and Preferences.')],'Project manager and architect','Expand minimum program requirements and distinguish preferences; review comparable development scope.'),
        manual('team.financial_capacity','Ability to finance entire project',[cite('stanns_rfp',18,'Applicants must demonstrate adequate','timely manner.')],'Finance lead','Review assets, commitments, equity and overruns capacity.'),
        manual('proposal.finance_feasibility','Feasible development and operating proposal',[cite('stanns_rfp',19,'The Applicant’s financing plan','Project budget.')],'Finance lead','Obtain credible costs, rents, comparables and supported sources/uses.'),
        manual('team.adverse_findings','Applicant and associated-party adverse findings',[cite('stanns_rfp',19,'An Applicant’s Proposal may be rejected','Department of Investigation.')],'Counsel','Collect adverse-finding disclosures and scoped legal review; no clearance inferred.'),
        manual('team.gc','General contractor identified at submission',[cite('stanns_add2',3,'Q12: The RFP states','for the proposal.')],'Project manager','Identify proposed general contractor and evidence its commitment.'),
        manual('submission.delivery','Historical deadline and required delivery format',[cite('stanns_rfp',21,'Proposals must be delivered by hand','May 22, 2015'),cite('stanns_rfp',21,'Each Proposal must include','original proposal.')],'Project manager','Verify historical delivery requirements in retrospective exercise; this is not a currently open solicitation.')]
    gates=[experience('team.development','Comparable development experience','development',dev,min_units,[eq('successful_completion',True),eq('as_principal',True),isin('work_type',['new_construction','substantial_rehabilitation'] if key=='west169' else ['new_construction'],work_domain)]+([eq('mixed_use',True)] if key=='west169' else []),'completion_date','Developer principal','Provide project/principal-role/completion evidence; '+('if criteria differ, prepare justified experience for HPD review without assuming approval.' if discretion else 'if unmet, assess qualified team changes; do not assume a waiver.'),discretion),
        experience('team.management','Comparable NYC management experience','management',mgmt,min_units,[eq('successful_management',True),eq('eligible_participant',True),eq('nyc',True),isin('ownership_role',['owner_and_manager','owner_through_management_entity'],role_domain)],'management_date','Proposed managing principal or agent','Provide reviewed NYC portfolio/unit and ownership/management-role history current at submission. Future experience cannot cure missing current evidence.'),*extras]
    if key=='stanns':gates[1]['citations'].append(cite('stanns_add2',3,'Q11: I’m aware','time of submission.'))
    case={'dsl_version':'0.1','id':key,'title':title,'cutoff':cutoff,'gates':gates,'coverage':{'threshold_gate_ids':[g['id'] for g in gates],'full_submission_inventory_review':'pending','unexpanded':'Referenced program, design/code and full form/attachment obligations require further scoped review. This inventory cannot certify full proposal completeness.'},'assumptions':[{'id':'window_anchor','value':cutoff,'rationale':'Use submission deadline as historical assessment anchor; inclusive calendar-year window. Boundary convention needs agency confirmation if material.'},{'id':'management_portfolio','rationale':'Management credential is a reviewed unique-unit portfolio for the required period, not necessarily one building. Never sum unreviewed overlapping project counts.'}],'limits':['Authored source interpretation, not an automated analyst benchmark.','No real applicant credentials supplied.','Rule check is not HPD acceptance or a selection probability.','Curator previously saw later summaries; outcomes excluded from this transfer test.']}
    cases.append(case);(BASE/'cases'/(key+'.json')).write_text(json.dumps(case,indent=2)+'\n')
print('Authored two cases:',[(c['id'],len(c['gates'])) for c in cases])
